INSERT INTO historical_events (id, well_id, depth, formation_id, event_type, severity, description, cause, mitigation, event_time) VALUES
  (1, 2, 2980.0, 11, 'MUD_LOSS', 'HIGH', 'Severe mud loss observed while penetrating upper Barail sandstone. Rate exceeded 45 bbls/hr.', 'Depleted pressure sand with subnormal pore pressure gradient (approx 0.38 psi/ft) causing fracture breakdown under 1.34 SG mud weight.', 'Spotted 50 bbls coarse CaCO3 LCM (Loss Circulation Material) pill; reduced active mud weight to 1.22 SG; staged resumption of circulation.', '2024-04-16T14:30:00'),
  (2, 7, 3010.0, 42, 'MUD_LOSS', 'HIGH', 'Encountered identical thief zone in Barail formation; 50 bbls total pit volume lost within 35 minutes.', 'Offset depletion zone extending from NWIS-W002; formation integrity unable to support hydrostatic head of 1.32 SG mud.', 'Pumped high-fluid-loss squeeze LCM pill with cellulosic fibers; reduced pump rate from 2400 L/min to 1750 L/min.', '2024-03-18T14:30:00'),
  (3, 11, 3040.0, 65, 'MUD_LOSS', 'MEDIUM', 'Partial dynamic mud loss of 20 bbls/hr while drilling through mid-Barail sand interval.', 'Marginal pressure depletion communicated through permeable sand channel from W002/W007 fault block.', 'Introduced medium-sized nut plug and mica flakes directly into active suction pit; stabilized return flow.', '2024-01-09T14:30:00'),
  (4, 15, 2995.0, 91, 'MUD_LOSS', 'HIGH', 'Sudden loss of returns (35 bbls/hr) at 2995m in Barail sand. Standpipe pressure dropped by 280 psi.', 'High permeability thief zone; pressure depletion confirmed by subsequent RFT logs.', 'Displaced hole with 1.20 SG low-solids mud; set viscous bentonite LCM plug.', '2024-11-24T14:30:00'),
  (5, 19, 3025.0, 115, 'LOST_CIRCULATION', 'CRITICAL', 'Total lost circulation encountered in Barail horizon; zero surface returns to shaker.', 'Severe regional pressure depletion combined with natural micro-fractures in upper Barail.', 'Bullheaded 80 bbls heavy LCM pill; pulled BHA into casing shoe to let well heal for 18 hours.', '2024-01-23T14:30:00'),
  (6, 4, 3520.0, 24, 'STUCK_PIPE', 'HIGH', 'Drillstring became mechanically stuck while pulling out of hole (POOH) at 3520m in Kopili shale.', 'Highly reactive smectite-rich Kopili shale hydration; borehole sloughing led to pack-off around 8-1/2 inch BHA.', 'Spotted 40 bbls glycol-weighted lubricant pill; worked pipe with upward jars at 70 tons; freed string after 6.5 hours.', '2021-10-04T09:15:00'),
  (7, 8, 3560.0, 48, 'STUCK_PIPE', 'CRITICAL', 'Severe drillstring pack-off while reaming tight spot in lower Kopili shale; rotation and circulation fully stalled.', 'Shale sloughing and borehole breakout caused by insufficient mud inhibition and low mud weight (1.28 SG).', 'Executed multiple high-impact jarring cycles; pumped acidic wash; freed string after 14 hours; resulted in 32 hrs NPT.', '2024-06-24T09:15:00'),
  (8, 14, 3490.0, 85, 'TORQUE_SPIKE', 'HIGH', 'Erratic torque spikes up to 41.5 kNm with intense string stalling while drilling Kopili shale interval.', 'Tight hole and cutting accumulation around stabilizer blades due to hole cleaning deficit in swollen shale.', 'Circulated high-viscosity tandem sweep; raised mud weight from 1.30 to 1.38 SG; back-reamed with controlled RPM.', '2023-12-09T09:15:00'),
  (9, 22, 3580.0, 134, 'STUCK_PIPE', 'HIGH', 'Pipe stuck during connection at 3580m; no upward movement possible.', 'Mechanically unstable overpressured Kopili shale spalling into wellbore cavity.', 'Applied 60 tons overpull with hydraulic jar; circulated clean with potassium chloride (KCl) polymer mud.', '2025-01-12T09:15:00'),
  (10, 3, 2240.0, 15, 'KICK', 'HIGH', 'Drilling break observed at 2240m in Tipam sandstone followed by 18 bbl pit gain and flow with pumps off.', 'Encountered localized high-pressure gas pocket charging permeable Tipam sand lenses.', 'Annular preventer shut in; measured SIDPP = 340 psi, SICP = 460 psi; executed Wait-and-Weight kill; raised MW to 1.28 SG.', '2024-05-27T22:10:00'),
  (11, 9, 2280.0, 52, 'HIGH_PRESSURE', 'CRITICAL', 'Formation pressure surge detected; gas cut mud reduced active mud weight from 1.20 to 1.04 SG at shaker.', 'Overpressured gas cap in Upper Tipam communicating along fault boundary.', 'Degasser engaged; shut in BOP; circulated out gas kick via choke manifold; densified mud to 1.31 SG.', '2021-08-18T22:10:00'),
  (12, 13, 2210.0, 75, 'HIGH_PRESSURE', 'MEDIUM', 'Standpipe pressure climbed by 380 psi; background gas on mud log jumped from 1.5% to 18.2%.', 'Pore pressure ramp in top Tipam sand exceeding planned balance.', 'Adjusted mud weight by +0.06 SG; reduced penetration rate to control gas dissolution rate.', '2024-01-12T22:10:00'),
  (13, 21, 2260.0, 125, 'KICK', 'HIGH', '14 bbl kick influx detected after drilling break in Tipam interval.', 'Underbalanced drilling condition due to unrecognized structural crest elevation in fault block.', 'Killed well using Driller''s method; circulated out influx bubble through mud-gas separator safely.', '2021-04-14T22:10:00'),
  (14, 1, 2779.49, 4, 'LOST_CIRCULATION', 'HIGH', 'Total loss of circulation while drilling 12-1/4 inch hole section.', 'Encountered natural fracture network in Upper Girujan formation.', 'Spotted high-viscosity cross-linked polymer pill; waited on cement plug.', '2021-09-21T21:48:00'),
  (15, 1, 969.21, 2, 'TORQUE_SPIKE', 'LOW', 'Transient torque flutter of +4 kNm during bit engagement in hard siltstone.', 'Bit tooth chatter upon contact with interbedded sandstone layer.', 'Adjusted rotary speed from 110 to 125 RPM and maintained steady bit weight.', '2021-09-27T21:37:00'),
  (16, 1, 2591.22, 4, 'LOST_CIRCULATION', 'LOW', 'Intermittent dynamic loss of 6 bbls during high pump rate circulation.', 'Annular friction pressure slightly exceeded local fracture gradient.', 'Reduced pump flow rate by 150 L/min and optimized mud rheology.', '2021-09-04T17:14:00'),
  (17, 2, 3247.59, 11, 'KICK', 'HIGH', '10 bbl influx taken while making connection; casing pressure elevated.', 'Swabbing effect during drillstring upward motion combined with formation gas saturation.', 'Shut in well on pipe rams; stripped back to bottom; circulated out gas bubble using choke manifold.', '2024-06-09T09:05:00'),
  (18, 2, 2416.89, 9, 'CEMENTING_ISSUE', 'LOW', 'Surface casing cement top found 25m below cellar floor after placement.', 'Normal slurry settling and consolidation in porous shallow alluvium.', 'Completed top-fill job through 1-inch tremie line with neat Portland cement.', '2024-04-23T18:19:00'),
  (19, 2, 1619.38, 8, 'CEMENTING_ISSUE', 'LOW', 'Surface casing cement top found 25m below cellar floor after placement.', 'Normal slurry settling and consolidation in porous shallow alluvium.', 'Completed top-fill job through 1-inch tremie line with neat Portland cement.', '2024-04-25T16:51:00'),
  (20, 2, 1578.09, 8, 'CEMENTING_ISSUE', 'HIGH', 'Poor cement bond log (CBL) across 9-5/8 inch casing shoe; channeling detected.', 'Inadequate mud displacement efficiency and gas channeling through setting cement slurry.', 'Perforated casing and performed remedial squeeze cementation; pressure tested shoe successfully.', '2024-04-19T12:56:00'),
  (21, 2, 647.3, 7, 'TORQUE_SPIKE', 'MEDIUM', 'Sudden torque spikes from 18 kNm to 29 kNm with stick-slip vibration.', 'Interbedded lithology change from soft shale to hard calcareous siltstone.', 'Reduced WOB from 24 klbf to 16 klbf; increased rotary speed to 125 RPM to suppress stick-slip.', '2024-05-20T20:22:00'),
  (22, 2, 573.35, 7, 'MUD_LOSS', 'MEDIUM', 'Seepage loss of 15-20 bbls/hr observed across porous sandstone interval.', 'Differential overbalance in porous sand facies.', 'Added fine calcium carbonate to active mud system; monitored pit levels closely.', '2024-06-05T10:43:00'),
  (23, 3, 1566.5, 14, 'NPT', 'LOW', '3.5 hours NPT for routine MWD pulse telemetry tool battery change-out.', 'Scheduled battery lifespan reached after 120 rotating hours.', 'Pulled shallow tool into BOP, replaced lithium battery pack, verified pulse signal.', '2024-05-20T15:29:00'),
  (24, 3, 1003.38, 14, 'HIGH_PRESSURE', 'MEDIUM', 'Connection gas increased to 12%; flow line temperature anomaly noted.', 'Approaching sub-regional pressure transition zone.', 'Raised mud weight by 0.05 SG; conducted flow check; verified well stability.', '2024-07-10T06:27:00'),
  (25, 3, 2000.81, 15, 'MUD_LOSS', 'LOW', 'Minor seepage loss of 3-5 bbls/hr while penetrating permeable sand stringer.', 'Normal filtration overbalance across permeable zone.', 'Added fine ground nut shells and mica sweep to mud pit; loss stabilized.', '2024-06-03T21:45:00'),
