  (116, 24, 3055.5, 146, 'TORQUE_SPIKE', 'MEDIUM', 'Sudden torque spikes from 18 kNm to 29 kNm with stick-slip vibration.', 'Interbedded lithology change from soft shale to hard calcareous siltstone.', 'Reduced WOB from 24 klbf to 16 klbf; increased rotary speed to 125 RPM to suppress stick-slip.', '2022-08-10T08:55:00'),
  (117, 25, 3625.1, 152, 'STUCK_PIPE', 'MEDIUM', 'Differential sticking occurred during 45-minute survey pause.', 'Thick filter cake deposited across permeable sandstone under 350 psi differential pressure.', 'Spotted low-toxicity oil-based spotting fluid across BHA; pipe pulled free after 90 minutes.', '2021-12-12T00:29:00'),
  (118, 25, 1207.98, 148, 'CEMENTING_ISSUE', 'MEDIUM', 'Premature cement slurry hydration during intermediate casing job.', 'Higher downhole temperature than predicted in laboratory thickening test.', 'Reversed out excess cement through drillpipe; cleared top of liner.', '2022-01-19T16:08:00'),
  (119, 25, 3173.22, 151, 'CEMENTING_ISSUE', 'HIGH', 'Poor cement bond log (CBL) across 9-5/8 inch casing shoe; channeling detected.', 'Inadequate mud displacement efficiency and gas channeling through setting cement slurry.', 'Perforated casing and performed remedial squeeze cementation; pressure tested shoe successfully.', '2021-12-19T22:31:00'),
  (120, 25, 2387.16, 149, 'KICK', 'HIGH', '10 bbl influx taken while making connection; casing pressure elevated.', 'Swabbing effect during drillstring upward motion combined with formation gas saturation.', 'Shut in well on pipe rams; stripped back to bottom; circulated out gas bubble using choke manifold.', '2021-12-26T11:41:00'),
  (121, 25, 2298.75, 149, 'HIGH_PRESSURE', 'LOW', 'Minor connection gas elevation up to 3.2% from background 1.1%.', 'Localized pore pressure fluctuation in transition stringer.', 'Maintained steady mud weight and increased circulation bottoms-up time.', '2022-01-23T06:09:00'),
  (122, 25, 2960.7, 151, 'KICK', 'HIGH', '10 bbl influx taken while making connection; casing pressure elevated.', 'Swabbing effect during drillstring upward motion combined with formation gas saturation.', 'Shut in well on pipe rams; stripped back to bottom; circulated out gas bubble using choke manifold.', '2021-12-01T21:36:00');
INSERT INTO reports (id, well_id, report_name, report_type, file_path, report_date, extracted_text) VALUES
  (1, 1, 'NWIS-W001 Daily Drilling Report #28', 'DDR', 'data/reports/NWIS-W001_DDR_Final_Section.txt', '2021-09-10', '===================================================================== DAILY DRILLING REPORT (DDR) - RIG 04 WELL: NWIS-W001 | FIELD: Demo-Dihing Basin (Fictional Field) OPERATING DATE: 2021-09-10 ===================================================================== SUMMARY OF OPERATIONS: Drilled 8-1/2 inch hole section from 2840.0m to 3110.0m in Demo-Barail formation. Average ROP: 14.8 m/hr. Flow rate: 2400 L/min. Active mud weight: 1.26 SG. Encountered differential pressure zone at 2980-3020m. Mud losses treated with medium calcium carbonate LCM sweep. Gas levels normal at 1.4%. Status at 06:00 hrs: Circulating bottoms up prior to bit change.'),
  (2, 1, 'NWIS-W001 Mud Logging Geological Evaluation', 'MUD_LOG', 'data/reports/NWIS-W001_Mud_Log_Summary.txt', '2021-09-27', '===================================================================== MUD LOGGING GEOLOGICAL EVALUATION WELL: NWIS-W001 | TOTAL DEPTH: 3561.82m ===================================================================== LITHOLOGICAL EVALUATION: - Demo-Tipam Sandstone (1620m - 2480m): Fine to medium grained quartzose sand,   good visible porosity, light yellow fluorescence, slow milky cut. - Demo-Barail (2860m - 3380m): Clean sandstone interbedded with carbonaceous   shale and thin sub-bituminous coal seams. Total Gas: peaks to 450 units. - Demo-Kopili Shale: Hard, dark grey fissile shale with moderate swelling potential.'),
  (3, 1, 'NWIS-W001 Well Completion Report', 'WCR', 'data/reports/NWIS-W001_Well_Completion_Report.txt', '2021-11-11', '===================================================================== WELL COMPLETION REPORT (WCR) WELL: NWIS-W001 | TARGET RESERVOIR: Demo-Barail Sand FINAL TOTAL DEPTH: 3561.82m TVD ===================================================================== COMPLETION DETAILS: 7-inch production liner set from 2650m to 3541.82m. Perforated interval: 3012.0m - 3028.0m with 4-1/2 inch tubing conveyed guns. Initial reservoir pressure: 3820 psi. Flow tested through 24/64 inch choke. Tubing head pressure (THP): 1420 psi. Produced clean sweet crude. Well handed over to production operations.'),
